                if (db != null && db.ResultSet.Tables.Count > 0)
                {
                    DataRow info = db.ResultSet.Tables[0].Rows[0];

                    pokerSetting.CustInfo = new CustDetail();
                    pokerSetting.CustInfo = getCustomerDetail(info);

                    pokerSetting.BetSetting = new BetSetting();
                    pokerSetting.BetSetting = getBetSetting(info);

                    pokerSetting.GameSettings = new List<GameTypeSetting>();
                    pokerSetting.GameSettings = getGameTypeSetting(db.ResultSet.Tables[1].Rows);

                    pokerSetting.GamesComm = new List<GameComm>();
                    if (db.ResultSet.Tables.Count > 2)
                    {
                        pokerSetting.GamesComm = getGameComm(db.ResultSet.Tables[2].Rows);
                    }
                }
                else
                {
                    pokerSetting.errCode = CastAide.AsInt16(db.Outputs["ErrCode"], 0);
