        public Result UpdatePoker(PokerSetting setting, int type)
        {
            var roleId = CastAide.AsInt32(setting.CustInfo.RoleId);

            int type1 = roleId * 10 + type;
            var result = new Result();
            result.ErrorHandler = new Dictionary<int, string>();
            try
            {
                var hostPermission = Permissions.GetHostPermission(Enumerations.Functions.Customer.Customer);
                if (!hostPermission)
                {
                    result.ErrorCode = 500;
                    result.ErrorMessage = ResourceExtension.GetResourceValue(ResourceExtension.Resources.ErrorMsg, "_500");
                    result.ErrorHandler.Add(result.ErrorCode, result.ErrorMessage);
                    return result;
                }
                var custId = CastAide.AsInt32(setting.CustInfo.CustId);
                var userId = AppSession.AccId;

                var settingParams = new Hashtable();

                // set cust param
                settingParams.Add("custid", custId);
                settingParams.Add("userid", userId);

                // static params
                var username = CastAide.AsString(setting.CustInfo.UserName);
                var ipClient = Utils.GetClientIP();
                settingParams.Add("subaccid", 0);
                settingParams.Add("language", "EN");
                settingParams.Add("username", username);
                settingParams.Add("errcode", 0);
                settingParams.Add("errmsg", "");
                settingParams.Add("ip", ipClient);

                switch (type)
                {
                    case 1:
                        setCommission(setting.GamesComm, ref settingParams);
                        break;
                    //case 2:
                    //    setGameType(setting.GameSettings, ref  settingParams);
                    //    break;
                    case 3:
                        setBetSetting(setting.BetSetting, ref settingParams);
                        break;

                    default:
                        break;
                }

                var dbResult = _pokerDAO.UpdateP2P(settingParams, type1);

                string errorMsg = dbResult.ErrorMessage;
                result.ErrorHandler.Add(dbResult.ErrorCode, errorMsg == string.Empty ? successMsg[type - 1] : errorMsg);
            }
            catch (Exception ex)
            {
                result.ErrorCode = 100;
                result.ErrorMessage = ex.Message;
                result.ErrorHandler.Add(result.ErrorCode, result.ErrorMessage);
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }

