        public Result UpdatePokerDefaultSettingMultiple(List<DefaultSettingItem> items)
        {
            var result = new Result();
            result.ErrorHandler = new Dictionary<int, string>();
            result.ErrorCode = 0;
            result.ErrorMessage = "";
            try
            {
                var hostPermission = Permissions.GetHostPermission(Enumerations.Admin.P2PDefaultSetting);
                if (!hostPermission)
                {
                    result.ErrorCode = 500;
                    result.ErrorMessage = ResourceExtension.GetResourceValue(ResourceExtension.Resources.ErrorMsg, "_500");
                    result.ErrorHandler.Add(result.ErrorCode, result.ErrorMessage);
                    return result;
                }

                var userId = AppSession.AccId;
                var ipClient = Utils.GetClientIP();

                foreach (DefaultSettingItem item in items)
                {
                    var settingParams = new Hashtable();
                    // static params
                    settingParams.Add("userid", userId);
                    settingParams.Add("subaccid", 0);
                    settingParams.Add("language", "EN");
                    settingParams.Add("errcode", 0);
                    settingParams.Add("errmsg", "");
                    settingParams.Add("ip", ipClient);

                    settingParams.Add("currency", CastAide.AsInt32(item.CurrencyID));
                    settingParams.Add("mincredit", CastAide.AsDecimal(item.MinCredit));
                    settingParams.Add("maxcredit", CastAide.AsDecimal(item.MaxCredit));
                    settingParams.Add("maxsdiscount", CastAide.AsDecimal(item.Maxsdiscount));
                    settingParams.Add("maxadiscount", CastAide.AsDecimal(item.Maxadiscount));
                    settingParams.Add("maxdiscount", CastAide.AsDecimal(item.Maxdiscount));
                    settingParams.Add("maxplayerdiscount", CastAide.AsDecimal(item.Maxplayerdiscount));
                    var dbResult = _pokerDAO.UpdateDefaultSettingP2P(settingParams);
                    if (dbResult.ErrorCode > 0)
                    {
                        result.ErrorHandler.Add(CastAide.AsInt32(item.CurrencyID), item.Currency + " - " + dbResult.ErrorMessage);
                    }
                }
            }
            catch (Exception ex)
            {
                result.ErrorCode = 100;
                result.ErrorMessage = ex.Message;
                result.ErrorHandler.Add(result.ErrorCode, result.ErrorMessage);
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }

        private void setCommission(List<GameComm> gameComms, ref Hashtable ht)
        {
            for (int i = 0; i < gameComms.Count; i++)
            {
                ht.Add(string.Format(discountDBFormat, i + 1), CastAide.AsDouble(gameComms[i].Comm, 0));
            }
        }

        private void setBetSetting(BetSetting betSetting, ref Hashtable ht)
        {
            ht.Add(maxTransferDBFormat, betSetting.TransferCredit);
            ht.Add(isDailyAutoResetDBFormat, betSetting.IsAutoReset);
        }

