            //{
            //  var gameType = gameTypes[i];
            for (int i = 0; i < gameType.StakeLevels.Count; i++)
            {
                ht.Add(string.Format(stakeLevelDBFormat, i + 1), gameType.StakeLevels[i].IsChecked);
            }
            ht.Add("bettype", CastAide.AsInt32(gameType.ID));
